<script lang="ts">import { defineComponent, type PropType } from 'vue'; import type { Chapter } from '../../api/models'; import AppButton from '../../ui/components/AppButton.vue'; export default defineComponent({name:'ReaderTocSheet',components:{AppButton},props:{chapters:{type:Array as PropType<Chapter[]>,default:()=>[]},currentIndex:{type:Number,required:true}},emits:['open','close']});</script>
<template><div class="overlay" @click.self="$emit('close')" @keydown.esc="$emit('close')"><section class="sheet" role="dialog" aria-modal="true" :aria-label="$t('reader.toc.title')"><header><div><h2>{{ $t('reader.toc.title') }}</h2><p>{{ $t('reader.toc.count',{count:chapters.length}) }}</p></div><AppButton variant="quiet" @click="$emit('close')">{{ $t('reader.close') }}</AppButton></header><ol><li v-for="chapter in chapters" :key="chapter.index" :class="{volume:chapter.isVolume,current:chapter.index===currentIndex}"><span v-if="chapter.isVolume">{{ chapter.title }}</span><button v-else type="button" @click="$emit('open',chapter.index)">{{ chapter.title }}</button></li></ol></section></div></template>
